import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, seq, active)
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def clean_buy():
        while buy_heap:
            negp, s, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            p, s, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        seq_counter += 1
        my_seq = seq_counter

        if side == 'buy':
            clean_sell()
            while remaining > 0 and sell_heap:
                p, s, sid = sell_heap[0]
                sorder = book.get(sid)
                if sorder is None or not sorder['active'] or sorder['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if price is not None and p > price:
                    break
                trade_qty = min(remaining, sorder['qty'])
                trades.append([oid, sid, p, trade_qty])
                remaining -= trade_qty
                sorder['qty'] -= trade_qty
                if sorder['qty'] <= 0:
                    sorder['active'] = False
                    heapq.heappop(sell_heap)
                clean_sell()
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': my_seq, 'active': True}
                heapq.heappush(buy_heap, (-price, my_seq, oid))
        else:  # sell
            clean_buy()
            while remaining > 0 and buy_heap:
                negp, s, bid = buy_heap[0]
                p = -negp
                border = book.get(bid)
                if border is None or not border['active'] or border['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if price is not None and p < price:
                    break
                trade_qty = min(remaining, border['qty'])
                trades.append([bid, oid, p, trade_qty])
                remaining -= trade_qty
                border['qty'] -= trade_qty
                if border['qty'] <= 0:
                    border['active'] = False
                    heapq.heappop(buy_heap)
                clean_buy()
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': my_seq, 'active': True}
                heapq.heappush(sell_heap, (price, my_seq, oid))

        if typ in ('limit',):
            if remaining < qty or remaining == qty:
                pass
        # store final state for limit orders that fully filled (already marked inactive not needed since not in book)
        if typ == 'limit' and remaining <= 0:
            # fully filled, no need to add to book, but if it was added above with remaining>0 only
            pass

    return trades

